'use strict';
let state=null, view='findings', selected=null, feed='', search='', recordKind='titles';
let researchPoll=null;
let voiceCleanup=null;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nice=v=>v===null||v===undefined?'Unavailable':Number(v).toLocaleString();
const date=v=>v==null?'Unavailable':new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const label=v=>v.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.hidden=false;}
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Desk-Token':state.csrf},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed.');return data;}
async function refresh(){clearTimeout(researchPoll);state=await api('/api/state?dataset='+$('#dataset').value);if(selected&&!state.candidates.some(x=>x.id===selected))selected=null;if(!selected&&state.candidates.length)selected=state.candidates[0].id;render();if(state.research_agent?.runs.some(r=>r.status==='RUNNING'))researchPoll=setTimeout(()=>refresh().catch(e=>toast(e.message,true)),2500);}
function openModal(html){if(voiceCleanup){voiceCleanup();voiceCleanup=null;}$('#modal-body').innerHTML=html;$('#modal').showModal();}
function render(){
  document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));
  const titles={findings:['Findings & decisions','Understand the evidence. Decide what to investigate, watch or test.'],frameworks:['Persistent frameworks','Versioned creative lenses. Changes require a separate editorial review.'],sources:['Sources','Save the creators, shows and references you want the team to study.'],inbox:['Intelligence desk','Find the signal. Understand the story. Choose what matters.'],briefs:['Editorial briefs','A short list of reviewed findings. Every decision keeps its evidence.'],runs:['Run history','See what ran, what changed, and what needs attention.'],setup:['Connections','Start with one working source. Expand when the evidence earns it.']};
  $('#page-title').textContent=titles[view][0];$('#page-subtitle').textContent=titles[view][1];
  $('#run').textContent=state.dataset==='demo'?'Load demo data':'Collect from YouTube';
  $('#run').disabled=state.dataset==='live'&&!state.settings.live_enabled;
  $('#run').hidden=!['inbox','setup'].includes(view);
  $('#notice').hidden=true;
  const research=state.candidates.filter(x=>x.latest.origin!=='firecrawl');
  const reviewed=research.filter(x=>x.decision).length;
  $('#overview').innerHTML=[['Research titles / videos',research.length],['Awaiting editorial review',research.length-reviewed],['Reviewed candidates',reviewed],['Saved briefs',state.briefs.length]].map(([a,b])=>`<div class="stat"><span>${a}</span><b>${b}</b></div>`).join('');
  if(view==='findings')renderFindings();if(view==='frameworks')renderFrameworks();if(view==='sources')renderSources();if(view==='inbox')renderInbox();if(view==='briefs')renderBriefs();if(view==='runs')renderRuns();if(view==='setup')renderSetup();
}
function renderInbox(){
  $('#workspace').innerHTML='<div class="desk"><div class="panel"><div class="panel-heading"><h2>Discovery inbox</h2><span class="label">Source-linked candidates</span></div><div class="tools"><select id="record-kind" aria-label="Record type"><option value="titles">Titles &amp; videos</option><option value="pages">Captured pages</option><option value="all">All records</option></select><input id="search" aria-label="Search candidates" placeholder="Search candidates…"><select id="feed" aria-label="Filter feed"><option value="">All feeds</option>'+state.feeds.map(f=>'<option>'+esc(f.id)+'</option>').join('')+'</select></div><div id="candidates"></div></div><div class="panel" id="detail"></div></div>';
  $('#search').value=search;$('#feed').value=feed;$('#record-kind').value=recordKind;
  $('#record-kind').onchange=e=>{recordKind=e.target.value;selected=null;renderCandidates();renderDetail();};
  $('#search').oninput=e=>{search=e.target.value;renderCandidates();renderDetail();};$('#feed').onchange=e=>{feed=e.target.value;renderCandidates();renderDetail();};renderCandidates();renderDetail();
}
function renderCandidates(){
  const rows=state.candidates.filter(x=>(recordKind==='all'||(recordKind==='pages')===(x.latest.origin==='firecrawl'))&&(!feed||x.latest.feed_ids.includes(feed))&&(`${x.latest.title} ${x.latest.channel_name}`).toLowerCase().includes(search.toLowerCase()));
  if(!rows.some(x=>x.id===selected))selected=rows[0]?.id||null;
  $('#candidates').innerHTML=rows.length?rows.map(x=>`<article class="candidate ${x.id===selected?'selected':''}" tabindex="0" role="button" data-id="${x.id}" aria-label="Open ${esc(x.latest.title)}"><div class="row"><span class="chip">${esc(x.latest.feed_ids.join(' · '))}</span><span class="chip ${x.decision?'reviewed':'pending'}">${x.decision?label(x.decision.route):'Needs review'}</span></div><h3>${esc(x.latest.title)}</h3><div class="row muted"><span>${esc(x.latest.channel_name)}</span><span>${date(x.latest.observed_at)}</span></div>${x.latest.origin==='catalog_title'?`<p class="muted">${esc(x.latest.kind)}${x.latest.genre?' · '+esc(x.latest.genre):''}<br>${x.latest.age_status==='MATURE_LABEL_REVIEW_REQUIRED'?'Mature label · suitability review required':'Age suitability unverified'}</p>`:x.latest.origin==='firecrawl'?'<p class="muted">Source page capture · extract individual titles</p>':`<div class="source-counts"><span><b>${nice(x.latest.metrics.views)}</b> views</span><span><b>${nice(x.latest.metrics.comments)}</b> comments</span></div>`}</article>`).join(''):'<div class="empty"><h2>No candidates yet</h2><p>'+ (state.dataset==='demo'?'Load demo data to try the review workflow.':'Use Sources → Test collection for website previews, or configure YouTube collection. Save captured results here for review.')+'</p></div>';
  document.querySelectorAll('.candidate').forEach(el=>{const choose=()=>{selected=el.dataset.id;renderCandidates();renderDetail();};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});
}
function renderDetail(){
  const item=state.candidates.find(x=>x.id===selected);
  if(!item){$('#detail').innerHTML='<div class="empty"><div class="eyebrow">A BETTER BRIEF STARTS HERE</div><h2>Choose a candidate</h2><p>Inspect its sources, record what you actually observed, and decide whether it deserves more research.</p></div>';return;}
  const source=item.latest, decision=item.decision;
  if(source.origin==='catalog_title'){renderResearchDetail(item);return;}
  $('#detail').innerHTML=`<div class="detail"><div class="row"><span class="label">Evidence packet</span><span class="chip">${state.dataset==='demo'?'Synthetic fixture':source.origin==='firecrawl'?'Website capture':source.origin==='catalog_title'?'Extracted title':'YouTube source'}</span></div><h2>${esc(source.title)}</h2><div class="muted">${esc(source.channel_name)} · Published ${date(source.published_at)}</div>${source.url?`<p><a href="${esc(source.url)}" target="_blank" rel="noreferrer">Inspect original source ↗</a></p>`:''}<div class="callout">${esc(source.inspection)}<br>${esc(source.series_status)}<br>${esc(item.measurement_note)}</div>${titleEvidence(source)}${source.origin==='firecrawl'?'<button id="extract-titles" class="primary">Extract research titles</button>':''}${source.captured_text?`<details class="section"><summary>Captured webpage text</summary><div class="longtext">${esc(source.captured_text)}</div><p class="muted">${source.truncated?'Capture was truncated; some page content is missing.':''} Not automatically sent to AI.</p></details>`:''}<div class="section"><div class="row"><h3>Three separate assessments</h3><span class="label">${decision?'Human reviewed':'Awaiting review'}</span></div><div class="scores">${['viral','story','execution'].map(k=>{const score=decision?.assessment[k]?.total;return `<div class="score"><span>${k==='story'?'Story / IP':label(k)}</span><strong>${score==null?'—':score}</strong><small>${score==null?'Not scored':'Editorial / 100'}</small></div>`;}).join('')}</div><p class="muted">No combined score. Missing evidence stays missing.</p><div class="actions"><button class="primary" id="review">Record decision</button><button id="add-note">Add evidence note</button><button id="analyze" ${item.notes.some(n=>n.analysis_allowed)?'':'disabled'}>${state.settings.model_enabled?'Draft with Claude':'Run evidence check'}</button></div></div><div class="section"><h3>Editorial evidence <span class="muted">(${item.notes.length})</span></h3>${item.notes.length?item.notes.map(n=>`<div class="note"><span class="muted">[${esc(n.evidence_type)}] ${esc(n.author)} · ${date(n.created_at)} · ${n.analysis_allowed?'Analysis allowed':'Local only'}</span>${esc(n.text)}<span class="muted spaced">Coverage: ${esc(n.coverage)}</span></div>`).join(''):'<p class="muted">No story conclusions yet. Add notes from material you have actually inspected.</p>'}</div>${item.analysis?`<div class="section"><h3>${item.analysis.method==='RULES_ONLY'?'Evidence readiness check':'AI draft · not approved'}</h3><p>${esc(item.analysis.result.summary)}</p>${item.analysis.result.hypotheses.map(h=>`<div class="note">${esc(h.text)}<small class="muted">Evidence: ${esc(h.quote)}</small></div>`).join('')}<ul class="muted">${item.analysis.result.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${['firecrawl','catalog_title'].includes(source.origin)?`<div class="section"><h3>Capture history</h3>${item.observations.map(o=>`<p>${date(o.observed_at)} · ${o.origin==='catalog_title'?'Title listing evidence':'Webpage text'}</p>`).join('')}</div>`:`<div class="section"><h3>Source snapshots</h3><table><thead><tr><th>Observed</th><th>Views</th><th>Likes</th><th>Comments</th></tr></thead><tbody>${item.observations.map(o=>`<tr><td>${date(o.observed_at)}</td><td>${nice(o.metrics.views)}</td><td>${nice(o.metrics.likes)}</td><td>${nice(o.metrics.comments)}</td></tr>`).join('')}</tbody></table></div>` }<div class="section"><h3>Decision history</h3>${item.decisions.length?item.decisions.map(d=>`<div class="review-log"><b>${label(d.route)}</b> · ${esc(d.author)}<p>${esc(d.rationale)}</p><span class="muted">${esc(d.primary_cohort||'Cohort unassigned')} · ${esc(d.confidence)} · ${date(d.created_at)}<br>Recommendation only. No execution authorized.</span></div>`).join(''):'<p class="muted">No editorial decision recorded.</p>'}<button class="danger spaced" id="delete">Delete local record</button></div></div>`;
  if($('#extract-titles'))$('#extract-titles').onclick=async e=>{e.target.disabled=true;try{const r=await api('/api/collection/extract',{candidate_id:item.id,save:true});recordKind='titles';selected=r.candidate_ids[0];await refresh();toast(`${r.count} title leads extracted. Original capture preserved; age and audience fit still need review.`);}catch(err){toast(err.message,true);e.target.disabled=false;}};
  $('#review').onclick=()=>decisionForm(item);$('#add-note').onclick=()=>noteForm(item);
  $('#analyze').onclick=async e=>{e.target.disabled=true;try{await api('/api/analyze',{candidate_id:item.id});await refresh();toast('Evidence review saved. Human approval is still required.');}catch(err){toast(err.message,true);e.target.disabled=false;}};
  $('#delete').onclick=async()=>{if(confirm('Delete this local record, notes and decisions? This does not delete anything on YouTube.')){try{await api('/api/delete',{candidate_id:item.id});await refresh();toast('Local record deleted.');}catch(err){toast(err.message,true);}}};
}
function noteForm(item){
  openModal(`<h2>Add an evidence note</h2><p class="muted">Record what you inspected and separate interpretation from observation. Do not paste private participant data or API-derived metrics into model inputs.</p><form class="form" id="note-form"><label>Reviewer name<input name="author" required maxlength="100"></label><div class="form-grid"><label>Evidence type<select name="evidence_type"><option value="O">Observed public behavior</option><option value="I">Interpretation / hypothesis</option><option value="D">Measured fact</option><option value="FP">First-party experiment</option></select></label><label>Inspection coverage<input name="coverage" placeholder="Episode / scene / timecode or transcript-only" required maxlength="500"></label></div><label>Evidence note<textarea name="text" required maxlength="10000"></textarea></label><label>Access / analysis basis<input name="access_basis" required maxlength="500" placeholder="How you may use this material"></label><label class="inline"><input type="checkbox" name="analysis_allowed">I permit analysis of these editorial notes, including transmission to the configured model provider when enabled.</label><div class="errors" id="form-error" role="alert"></div><button class="primary">Save evidence</button></form>`);
  $('#note-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.analysis_allowed=e.target.analysis_allowed.checked;data.candidate_id=item.id;await submit('/api/note',data);};
}
function decisionForm(item){
  const previous=item.decision;
  openModal(`<h2>Record an editorial decision</h2><p class="muted">This records a recommendation. TEST and DEVELOP PILOT do not start production. Keep the three assessments separate.</p><form id="decision-form" class="form"><div class="form-grid"><label>Reviewer name<input name="author" required maxlength="100" value="${esc(previous?.author||'')}"></label><label>Recommended route<select name="route">${state.routes.map(x=>`<option ${previous?.route===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Primary behavioral cohort<select name="primary_cohort"><option value="">Unassigned</option>${state.cohorts.map(x=>`<option ${previous?.primary_cohort===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Rights status<select name="rights_status">${['UNREVIEWED','ORIGINAL_PROPOSAL','REQUIRES_LICENSE','REVIEWED'].map(x=>`<option ${previous?.rights_status===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Decision rationale<textarea name="rationale" required maxlength="6000">${esc(previous?.rationale||'')}</textarea></label><div class="form-grid"><label>Confidence<input name="confidence" required maxlength="100" placeholder="Low / medium / high, with context" value="${esc(previous?.confidence||'')}"></label><label>Sample size / evidence availability<input name="sample_size_note" required maxlength="500" placeholder="Not measured, or actual denominator" value="${esc(previous?.sample_size_note||'')}"></label></div><p class="muted">Optional component assessments: leave blank when unknown. Ratings require an analysis-permitted editorial note and a rationale. Do not calculate ratings from standard YouTube API counters.</p>${Object.entries(state.weights).map(([kind,weights])=>`<details class="score-fields"><summary>${kind==='story'?'Story / IP':label(kind)} assessment</summary><div class="form-grid">${Object.entries(weights).map(([key,weight])=>`<label>${label(key)} · ${weight}%<input type="number" name="${kind}.${key}" min="0" max="100" step="any" placeholder="Unknown" value="${esc(previous?.assessment[kind]?.components[key]??'')}"></label>`).join('')}</div><label>Rationale<input name="${kind}.rationale" maxlength="6000" value="${esc(previous?.assessment[kind]?.rationale||'')}"></label><label>Supporting editorial note<select name="${kind}.evidence"><option value="">None</option>${item.notes.filter(n=>n.analysis_allowed).map(n=>`<option value="${n.id}" ${previous?.assessment[kind]?.evidence_ids.includes(n.id)?'selected':''}>${esc(n.text.slice(0,80))}</option>`).join('')}</select></label></details>`).join('')}<div class="errors" id="form-error" role="alert"></div><button class="primary">Save decision</button></form>`);
  $('#decision-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const payload={candidate_id:item.id,author:f.author,route:f.route,primary_cohort:f.primary_cohort||null,rights_status:f.rights_status,rationale:f.rationale,confidence:f.confidence,sample_size_note:f.sample_size_note,assessment:{}};for(const[kind,weights]of Object.entries(state.weights)){payload.assessment[kind]={components:Object.fromEntries(Object.keys(weights).map(k=>[k,f[`${kind}.${k}`]===''?null:Number(f[`${kind}.${k}`])])),rationale:f[`${kind}.rationale`],evidence_ids:f[`${kind}.evidence`]?[f[`${kind}.evidence`]]:[]};}await submit('/api/decision',payload);};
}
async function submit(path,data){const button=$('#modal form button');button.disabled=true;try{await api(path,data);$('#modal').close();await refresh();toast(path==='/api/framework'?'New framework draft saved. Previous approvals remain unchanged.':path==='/api/framework/approve'?'Editorial approval recorded for this version.':path==='/api/feed'?'Feed saved. Collector settings and monitoring have not changed.':path==='/api/source'?'Source saved. Monitoring has not started.':'Saved to the local decision history.');}catch(err){$('#form-error').textContent=err.message;button.disabled=false;}}
function renderBriefs(){
  $('#workspace').innerHTML=`<div class="row"><h2>Your editorial shortlist</h2><div class="actions"><button class="primary" data-make="daily">Build daily brief · max 5</button><button data-make="weekly">Build weekly shortlist · max 3</button></div></div><p class="muted">Only reviewed candidates are eligible. Each period is frozen once created; no invented findings or repeated leaderboard.</p><div class="brief-grid">${state.briefs.map(b=>`<div class="panel brief-card"><span class="label">${esc(b.kind)} · ${esc(b.dataset)}</span><h2 class="spaced">${esc(b.period)}</h2><p class="muted">Created ${date(b.created_at)}</p><button data-brief="${b.id}">Open brief ↗</button></div>`).join('')||'<div class="panel empty"><h2>A brief worth reading</h2><p>Review a candidate in the inbox, then build your first brief.</p></div>'}</div>`;
  document.querySelectorAll('[data-make]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const brief=await api('/api/brief',{dataset:state.dataset,kind:b.dataset.make});await refresh();showBrief(brief);}catch(err){toast(err.message,true);b.disabled=false;}});
  document.querySelectorAll('[data-brief]').forEach(b=>b.onclick=async()=>{try{showBrief(await api('/api/brief/'+b.dataset.brief));}catch(err){toast(err.message,true);}});
}
function showBrief(b){openModal(`<div class="eyebrow">${esc(b.dataset)} · ${esc(b.kind)}</div><h2>${esc(b.period)}</h2><p class="muted">${esc(b.note)}</p>${b.items.length?b.items.map(x=>`<div class="section"><span class="chip">${esc(x.decision.route)}</span><h3 class="spaced">${esc(x.latest.title)}</h3><p>${esc(x.decision.rationale)}</p><p class="muted">${esc(x.decision.primary_cohort||'Cohort unassigned')} · ${esc(x.decision.confidence)}<br>No production authorized.</p></div>`).join(''):'<div class="callout">No new reviewed findings in this brief.</div>'}<p class="spaced"><a href="/api/brief/${b.id}/export">Download Markdown brief</a></p>`);}
function renderRuns(){
  $('#workspace').innerHTML=`<div class="panel"><div class="panel-heading"><h2>Collection history</h2><span class="label">${esc(state.dataset)} workspace</span></div>${state.runs.length?state.runs.map(r=>`<div class="run"><div><b>${date(r.started_at)}</b><div class="muted">${r.finished_at?'Finished '+date(r.finished_at):'Not finished'}</div></div><div><span class="chip ${r.status==='COMPLETED'?'reviewed':'pending'}">${esc(r.status)}</span></div><div class="muted">${Object.entries(r.counts).map(([k,v])=>`${esc(label(k))}: ${esc(v)}`).join('<br>')}</div>${r.errors.length?`<p>${r.errors.map(esc).join('<br>')}</p>`:''}</div>`).join(''):'<div class="empty"><h2>No runs yet</h2><p>Load the synthetic workspace, or configure live collection.</p></div>'}</div>`;
  $('#workspace').insertAdjacentHTML('beforeend',`<div class="panel setup-card"><h2>Website previews · last 24 hours</h2>${(state.collection_previews||[]).map(p=>`<p>${date(p.created_at)} · ${esc(p.status)} <button data-preview="${p.id}">Open preview</button></p>`).join('')||'<p>No website tests yet.</p>'}</div>`);
  document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewForm(state.collection_previews.find(p=>p.id===b.dataset.preview)));
}
function renderSetup(){
  $('#workspace').innerHTML=`<div class="setup-grid"><div class="panel setup-card"><h2>Website collection · Firecrawl</h2><p>${state.website_collection.connected?'Key configured · ready for a test':'Not connected · API key needed'}</p><p>Test up to three supported public website links from Sources, inspect the preview, then save selected captures to the inbox. No schedule is started.</p><button id="connect-firecrawl">${state.website_collection.connected?'Replace Firecrawl key':'Connect Firecrawl'}</button><p class="muted">Your key is stored privately on this computer and excluded from GitHub. Saving it does not request pages or start monitoring.</p></div><div class="panel setup-card"><span class="label">First working integration</span><h2 class="spaced">YouTube discovery</h2><p class="muted">F02 scripted-series candidates, F04 gaming candidates, and F07 verified authority channels. Metadata is a starting point, not a viewing audit or confirmed series grouping.</p><div class="feed"><span>Live collection</span><span class="chip">${state.settings.live_enabled?'Configured on':'Off'}</span></div><div class="feed"><span>Verified panel channel IDs</span><b>${state.settings.panel_configured} / 10</b></div><div class="feed"><span>Daily request ceiling</span><b>${state.settings.max_daily_requests}</b></div><p class="muted">Initialize private settings with <code>python3 -m intelligence init</code>. Set <code>YOUTUBE_API_KEY</code> outside the browser, then enable collection in the private config. Never paste credentials into notes.</p></div><div class="panel setup-card"><span class="label">Evidence review</span><h2 class="spaced">Human judgment, supported</h2><div class="feed"><span>Claude drafts</span><span class="chip">${state.settings.model_enabled?'Configured on':'Off · rules only'}</span></div><div class="feed"><span>Scheduler</span><span class="muted">Not installed</span></div><div class="feed"><span>Production and publication</span><span class="chip pending">Paused</span></div><p class="muted">Optional model calls use only explicitly permitted editorial notes. Model drafts require review; citations are checked against the supplied notes. No tools, media downloads or autonomous execution.</p></div><div class="panel setup-card"><h2>Feed architecture</h2>${state.feeds.map(f=>`<div class="feed"><span>${esc(f.id)} · ${esc(f.name)}</span><span class="chip">${['F02','F04','F07'].includes(f.id)?'YouTube adapter':state.sources.some(s=>s.feed_id===f.id&&!state.website_collection.sources[s.id])?'Website pilot adapter':'Planned'}</span></div>`).join('')}</div><div class="panel setup-card"><h2>Before going live</h2><ol class="muted"><li>Verify API access and the ten panel accounts.</li><li>Run the live collector explicitly and inspect its coverage.</li><li>Review genuine evidence before publishing a brief.</li><li>Evaluate usefulness and reviewer corrections.</li><li>Configure a private host and authentication before team deployment.</li></ol><div class="callout">${state.deployment?.hosted?'Hosted on Google Cloud. Access is protected by Google sign-in.':'This server is accessible only on this computer.'}</div><h3 class="spaced">Source handling</h3><p class="muted">No metric-derived rankings from standard YouTube API data. Live source records and related annotations expire after 29 days. Deleted/unavailable videos are removed on refresh. Sources are not sent to the model automatically.</p></div></div>`;
  $('#workspace').insertAdjacentHTML('afterbegin',`<div class="panel setup-card"><h2>Research agent · ${state.research_agent.provider==='openai'?'OpenAI':'Claude'}</h2><p>${state.research_agent.model_configured?'Key configured · validate with a research run':'Provider key needed'}</p><p>Research retrieves a supported title page through Firecrawl, sends its text plus the feed research objective and approved framework to the selected provider, and saves a cited AI draft. Up to 3 titles per batch and 5 model requests per day. Provider credits may be used; no schedules or production start.</p><button id="connect-research">Configure research agent</button></div>`);
  $('#connect-research').onclick=researchConnectionForm;
  $('#connect-firecrawl').onclick=firecrawlForm;
}
$('#close-modal').onclick=()=>$('#modal').close();
$('#dataset').onchange=async()=>{$('#toast').hidden=true;selected=null;search='';feed='';try{await refresh();}catch(err){toast(err.message,true);}};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});
$('#run').onclick=async()=>{const b=$('#run');b.disabled=true;b.textContent='Working…';try{const result=await api(state.dataset==='demo'?'/api/demo':'/api/collect',{});await refresh();toast(result.status==='COMPLETED'?(state.dataset==='demo'?'Demo data loaded. These are synthetic records.':`Live collection finished: ${result.counts?.refreshed||0} items refreshed. Check Run history for coverage.`):'Collection '+result.status.toLowerCase()+'. See Run history for details.',result.status==='FAILED');}catch(err){toast(err.message,true);render();}};
$('#privacy').onclick=()=>openModal('<h2>Data & privacy</h2><p>'+ (state.deployment?.hosted?'Records and saved connections are stored on the dedicated Bumpp Intelligence server. Google sign-in controls access.':'Records and saved connections are stored on this computer.') +'</p><p>Collection sends requests to the configured source services. Research sends source text, selected framework context and feedback to the selected OpenAI or Claude provider. Keys are stored privately and never returned in app state.</p><p>Live source records and linked findings expire after 29 days. Durable approved editorial lessons are stored separately. Deleting a candidate removes its linked research, not the original source website.</p><p>Do not store identifiable youth data, private messages or secrets in research notes. Voice dictation may use your browser vendor’s transcription service.</p>');
refresh().catch(err=>toast(err.message,true));

function renderSources(){
  $('#workspace').innerHTML=intelligenceUniverse();
  const imported=(state.registry_imports||[])[0];
  if(imported){const r=JSON.parse(imported.report);$('#workspace').insertAdjacentHTML('afterbegin',`<details class="panel setup-card source-group"><summary>V2 import &amp; mapping report</summary><p>${r.feeds_updated} feeds updated · ${r.feeds_added} added · ${r.sources_updated} sources updated · ${r.sources_added} added. Existing IDs and history preserved.</p><ul>${r.mappings.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>${issueList(r.issues.map(x=>x.entity+': '+x.issue))}<p class="muted">Persistent lenses imported as draft versions. No connector was activated.</p></details>`);}
  $('#add-source').onclick=()=>sourceForm();
  $('#test-web').onclick=()=>collectionForm();
  document.querySelectorAll('[data-test-source]').forEach(b=>b.onclick=()=>collectionForm(b.dataset.testSource));
  $('#add-feed').onclick=()=>feedForm();
  document.querySelectorAll('[data-edit-feed]').forEach(b=>b.onclick=()=>feedForm(state.feeds.find(f=>f.id===b.dataset.editFeed)));
  document.querySelectorAll('[data-add-to-feed]').forEach(b=>b.onclick=()=>sourceForm({feed_id:b.dataset.addToFeed}));
  document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceForm(state.sources.find(s=>s.id===b.dataset.source)));
}
function sourceForm(s={}){
  openModal(`<h2>${s.id?'Edit source':'Add source'}</h2><p class="muted">Paste a public channel, show, episode or reference link. No API key is needed to save it.</p><form id="source-form" class="form"><label>Name<input name="name" required maxlength="200" value="${esc(s.name||'')}" placeholder="e.g. Walden Academy"></label><label>Source link (optional until verified)<input name="url" type="url" maxlength="2000" value="${esc(s.url||'')}" placeholder="https://www.youtube.com/@creator"></label><div class="form-grid"><label>Source type<select name="kind">${['Creator / channel','Show / series','Episode / scene','Creative reference','Trend / topic'].map(k=>`<option ${s.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Feed<select name="feed_id">${state.feeds.filter(f=>f.active||f.id===s.feed_id).map(f=>`<option value="${f.id}" ${(s.feed_id||'F02')===f.id?'selected':''}>${esc(f.id+' · '+f.name)}</option>`).join('')}</select></label></div><label>Research role<select name="role">${['Discovery','Creative reference','Authority panel','Supporting research'].map(r=>`<option ${(s.role||'Creative reference')===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Anything specific to investigate? (optional)<textarea name="notes" maxlength="30000">${esc(s.notes||'')}</textarea></label><label class="inline"><input name="active" type="checkbox" ${s.active!==false?'checked':''}>Keep in active reference list (uncheck to archive)</label><p class="muted">Status after saving: saved, not monitoring. This does not verify the source, inspect its content or authorize reuse.</p><div class="errors" id="form-error" role="alert"></div><button class="primary">Save source</button></form>`);
  $('#source-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.active=e.target.active.checked;if(s.id)data.id=s.id;await submit('/api/source',data);};
}

function intelligenceUniverse(){
  const sources=state.sources||[];
  return `<div class="row"><h2>Feeds &amp; sources</h2><div class="actions"><button id="test-web" class="primary">Test collection</button><button id="add-feed">Add feed</button><button id="add-source">Add source</button></div></div><p class="muted">${state.feeds.length} feeds · ${sources.length} sources. Research definitions and source links are editable. Persistent lenses live in Frameworks; live observations and first-party outcomes remain separate. Saving does not activate monitoring.</p><div class="setup-grid">${state.feeds.map(f=>{const members=sources.filter(s=>s.feed_id===f.id);return `<article class="panel setup-card"><div class="row"><span class="chip">${esc(f.id)} · ${esc(f.priority)} · ${f.intelligence_class==='first_party_performance'?'First-party performance':'Live cultural intelligence'}</span><span class="chip pending">${f.active?'Not connected':'Archived definition'}</span></div><h2 class="spaced">${esc(f.name)}</h2><details class="section"><summary>Full research brief</summary><div class="longtext">${esc(f.universe)}</div></details><p class="muted">${esc(f.relevance_filter)}</p><p class="muted">Desired frequency: ${esc(f.cadence_proposed)}</p>${issueList(f.import_issues)}<details><summary>Research settings</summary>${(f.entry_points||[]).map(u=>`<p><a href="${esc(u)}" target="_blank" rel="noreferrer">${esc(u)}</a></p>`).join('')}<p class="muted">Searches: ${esc((f.seed_queries||[]).join(' · ')||'None specified')}</p><p class="muted">Communities: ${esc((f.candidate_community_allowlist||[]).join(' · ')||'None specified')}</p></details><div class="actions"><button data-edit-feed="${f.id}">Edit feed</button>${f.active?`<button data-add-to-feed="${f.id}">Add source to feed</button>`:''}</div><div class="section"><h3>Sources · ${members.length}</h3>${members.map(s=>`<div class="note"><div class="row"><strong>${esc(s.name)}</strong><div class="actions"><button data-source="${s.id}">Edit source</button>${s.active&&!state.website_collection.sources[s.id]?`<button data-test-source="${s.id}">Test collection</button>`:''}</div></div><p class="muted">${esc(s.role||'Creative reference')} · ${s.active?(s.url?(s.verification_status==='VERIFIED'?'Verified link · not monitoring':s.link_kind==='DISCOVERY_SEARCH'?'Search link · verification needed':'Saved link · not verified'):'Endpoint / account link needed'):'Archived'}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.url)}</a>`:''}<details><summary>Research objective</summary><div class="longtext">${esc(s.notes)}</div></details>${issueList(s.import_issues)}</div>`).join('')||'<p class="muted">No saved sources. Add links or define discovery searches in Edit feed.</p>'}</div></article>`;}).join('')}</div>`;
}

function feedForm(f={}){
  const field=(key,title,rows=false)=>`<label>${title}${rows?`<textarea name="${key}" required maxlength="30000">${esc(f[key]||'')}</textarea>`:`<input name="${key}" required maxlength="200" value="${esc(f[key]||'')}">`}</label>`;
  const list=(key,title)=>`<label>${title}<textarea name="${key}" placeholder="One entry per line">${esc((f[key]||[]).join('\n'))}</textarea></label>`;
  openModal(`<h2>${f.id?'Edit feed · '+esc(f.id):'Add research feed'}</h2><p class="muted">Define the research scope. Saving changes does not configure a collector or start monitoring.</p><form class="form" id="feed-form">${field('name','Feed name')}<div class="form-grid"><label>Kind<select name="kind"><option value="external">External research</option><option value="internal" ${f.kind==='internal'?'selected':''}>Internal learning</option></select></label><label>Priority<select name="priority">${['P0','P1','P2'].map(p=>`<option ${p===(f.priority||'P1')?'selected':''}>${p}</option>`).join('')}</select></label></div>${field('universe','What should this feed discover?',true)}${field('relevance_filter','What should it include or exclude?',true)}${field('cadence_proposed','Desired review frequency')}${list('entry_points','Starting links (HTTPS, one per line)')}${list('seed_queries','Discovery searches / hashtags (one per line)')}${list('candidate_community_allowlist','Communities to review (one per line)')}<label class="inline"><input type="checkbox" name="active" ${f.active!==false?'checked':''}>Available for source assignment (uncheck to archive)</label><p class="muted">Archiving preserves assigned sources and existing evidence. It does not stop an independently configured collector. Restore a feed by checking this box again.</p><div id="form-error" class="errors" role="alert"></div><button class="primary">Save feed</button></form>`);
  $('#feed-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.active=e.target.active.checked;for(const key of ['entry_points','seed_queries','candidate_community_allowlist'])data[key]=data[key].split('\n').map(x=>x.trim()).filter(Boolean);if(f.id){data.id=f.id;data.version=f.version;}await submit('/api/feed',data);};
}

function issueList(issues){return issues?.length?`<details class="review-issues"><summary>${issues.length} setup / review notes</summary><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:'';}
function renderFrameworks(){
  const versions=state.frameworks||[];
  $('#workspace').innerHTML=`<div class="callout">Persistent frameworks are stored separately from live observations and first-party outcomes. Imported lenses are proposals, not validated findings. Review quarterly; no trend or collector can automatically approve or overwrite a framework.</div><p class="muted">First-party performance records: ${state.performance_records||0}. Analytics connectors and outcome validation remain unconfigured.</p><div class="setup-grid">${state.feeds.map(f=>{const history=versions.filter(v=>v.feed_id===f.id);const latest=history[0];const approved=history.find(v=>v.approvals.length);return `<article class="panel setup-card"><span class="chip">${esc(f.id)} · persistent framework</span><h2 class="spaced">${esc(f.name)}</h2><p class="muted">Latest: ${latest?'v'+latest.version:'No proposal'} · Approved lens: ${approved?'v'+approved.version:'None'}</p>${latest?`<details><summary>Read latest proposal</summary><div class="longtext">${esc(latest.content)}</div><p class="muted">${esc(latest.provenance)}</p></details>`:''}<div class="actions"><button data-framework="${f.id}">${latest?'Propose revision':'Create proposal'}</button>${latest&&!latest.approvals.length?`<button data-approve="${latest.id}">Review &amp; approve</button>`:''}</div><details class="section"><summary>Version history · ${history.length}</summary>${history.map(v=>`<div class="note"><strong>v${v.version} · ${v.approvals.length?'Editorially approved':'Draft'}</strong><p class="muted">${date(v.created_at)}</p><details><summary>Content &amp; provenance</summary><div class="longtext">${esc(v.content)}</div><p>${esc(v.provenance)}</p></details>${v.approvals.map(a=>`<p class="muted">${esc(a.reviewer)} · ${date(a.approved_at)}<br>${esc(a.rationale)}<br>Evidence: ${esc(a.evidence)}</p>`).join('')}</div>`).join('')}</details></article>`;}).join('')}</div>`;
  document.querySelectorAll('[data-framework]').forEach(b=>b.onclick=()=>frameworkForm(b.dataset.framework));
  document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approvalForm(b.dataset.approve));
}
function frameworkForm(feedId){
  const latest=(state.frameworks||[]).find(v=>v.feed_id===feedId);
  openModal(`<h2>Propose framework revision · ${esc(feedId)}</h2><p class="muted">Creates a new draft version. Existing approved lenses remain unchanged.</p><form class="form" id="framework-form"><label>Enduring principles and audience psychology<textarea name="content" required maxlength="30000">${esc(latest?.content||'')}</textarea></label><label>Evidence, provenance and reason for revision<textarea name="provenance" required maxlength="6000"></textarea></label><div id="form-error" class="errors" role="alert"></div><button class="primary">Save draft version</button></form>`);
  $('#framework-form').onsubmit=async e=>{e.preventDefault();await submit('/api/framework',{...Object.fromEntries(new FormData(e.target)),feed_id:feedId,base_version:latest?.version||0});};
}
function approvalForm(id){
  openModal(`<h2>Editorial framework approval</h2><p class="muted">Approve only after inspecting the proposed version and its supporting research. Approval does not validate a demographic claim or authorize production.</p><form id="approval-form" class="form"><label>Reviewer<input name="reviewer" required maxlength="100"></label><label>Approval rationale<textarea name="rationale" required maxlength="6000"></textarea></label><label>Evidence reviewed, population and limits<textarea name="evidence" required maxlength="6000"></textarea></label><div id="form-error" class="errors" role="alert"></div><button class="primary">Approve this version</button></form>`);
  $('#approval-form').onsubmit=async e=>{e.preventDefault();await submit('/api/framework/approve',{...Object.fromEntries(new FormData(e.target)),id});};
}

function collectionForm(sourceId){
  const c=state.website_collection;
  openModal(`<h2>Test website collection</h2><p>Choose up to ${c.max_pages} saved links. Each link requests one page through Firecrawl. No whole-site crawl or schedule. Daily ceiling: ${c.daily_pages} page requests; provider credits may be used.</p><p class="muted">Only the selected public URLs are sent to Firecrawl. Research notes and frameworks stay local. Captures are previews until you save them.</p>${!c.connected?'<div class="callout">Firecrawl is not connected. Open Connections → Connect Firecrawl to add your key privately. Do not paste it into chat or source notes. <button type="button" id="connect-from-test">Connect Firecrawl</button></div>':''}<form id="test-collection" class="form">${state.sources.filter(s=>s.active&&!c.sources[s.id]).map(s=>`<label class="inline"><input type="checkbox" name="source" value="${esc(s.id)}" ${c.sources[s.id]?'disabled':''} ${s.id===sourceId&&!c.sources[s.id]?'checked':''}><span>${esc(s.name)} · ${esc(s.feed_id)}<small class="muted spaced">${esc(c.sources[s.id]||s.url)}</small></span></label>`).join('')}<details><summary>Other sources · connector requirements</summary>${state.sources.filter(s=>s.active&&c.sources[s.id]).map(s=>`<p><b>${esc(s.name)}</b><br>${esc(c.sources[s.id])}</p>`).join('')}</details><div id="collection-error" class="errors" role="alert"></div><button class="primary" ${c.connected?'':'disabled'}>Run small batch</button></form>`);
  if($('#connect-from-test'))$('#connect-from-test').onclick=firecrawlForm;
  $('#test-collection').onsubmit=async e=>{e.preventDefault();const ids=new FormData(e.target).getAll('source');const b=e.target.querySelector('button');if(!ids.length||ids.length>c.max_pages){$('#collection-error').textContent='Choose one to three sources.';return;}b.disabled=true;b.textContent='Capturing pages…';try{const p=await api('/api/collection/test',{source_ids:ids});await refresh();previewForm(p);}catch(err){$('#collection-error').textContent=err.message;b.disabled=false;b.textContent='Run small batch';}};
}
function previewForm(p){
  openModal(`<h2>Collection preview · ${esc(p.status)}</h2><p class="muted">Inspect the captured text before saving. Previews expire after 24 hours. A captured page can still be incomplete or contain a consent wall.</p><form id="save-preview" class="form">${p.results.map(x=>`<div class="section"><h3>${esc(x.name)}</h3><a href="${esc(x.url)}" target="_blank" rel="noreferrer">${esc(x.url)}</a>${x.status==='CAPTURED'?`<p>${esc(x.title)} · Captured ${date(x.observed_at)}</p><p class="muted">${esc(x.warning)}${x.truncated?' Capture was truncated at the storage limit.':''}</p><details><summary>Read captured text</summary><div class="longtext">${esc(x.text)}</div></details><label class="inline"><input type="checkbox" name="source" value="${esc(x.source_id)}" ${x.saved_candidate_id?'disabled':''}>${x.saved_candidate_id?'Already saved to inbox':'Save this page to inbox'}</label>`:`<p class="errors">${esc(x.error)}</p>`}</div>`).join('')}<div id="collection-error" class="errors" role="alert"></div><button class="primary" ${p.results.some(x=>x.status==='CAPTURED'&&!x.saved_candidate_id)?'':'disabled'}>Save selected to inbox</button></form>`);
  $('#save-preview').onsubmit=async e=>{e.preventDefault();const ids=new FormData(e.target).getAll('source');const b=e.target.querySelector('button');b.disabled=true;try{const result=await api('/api/collection/save',{preview_id:p.id,source_ids:ids});$('#modal').close();view='inbox';recordKind=result.title_ids?.length?'titles':'pages';selected=result.title_ids?.[0]||result.candidate_ids[0];await refresh();toast(`Pages saved. ${result.title_ids?.length||0} title leads extracted; inspect their evidence before drawing conclusions.`);}catch(err){$('#collection-error').textContent=err.message;b.disabled=false;}};
}

function firecrawlForm(){
  openModal('<h2>Connect Firecrawl</h2><p>Enter your Firecrawl API key. It stays in a private file on the workbench server, is never displayed again, and is sent only to Firecrawl when you run a test. Saving the key does not validate it or start collection.</p><form id="firecrawl-key-form" class="form"><label>API key<input name="key" type="password" required maxlength="500" autocomplete="off" spellcheck="false"></label><div id="form-error" class="errors" role="alert"></div><button class="primary">Save private connection</button></form>');
  $('#firecrawl-key-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/connection/firecrawl',{key:e.target.elements.key.value});e.target.reset();$('#modal').close();view='sources';await refresh();toast('Key saved. Use Test collection to check access and capture a page.');}catch(err){$('#form-error').textContent=err.message;b.disabled=false;}};
}

function titleEvidence(){return '';}
const actionNames={INVESTIGATE:'Investigate further',WATCH:'Watch for more evidence',REJECT:'Deprioritize',PROPOSE_TEST:'Propose a test'};
function latestFinding(cid){return (state.findings||[]).filter(f=>f.candidate_id===cid).sort((a,b)=>b.version-a.version)[0];}
function sectionHeading(f,key,title,interactive){return `<div class="brief-section-heading"><h3>${esc(title)}</h3>${interactive?`<button data-comment-section="${key}" data-comment-finding="${f.id}" aria-label="Comment: ${esc(feedbackSections[key])}">Comment</button>`:''}</div>`;}
function sectionComments(f,key,interactive){return (state.editorial?.comments||[]).filter(c=>c.finding_id===f.id&&c.section===key).map(c=>`<article class="note section-comment"><b>${esc(c.kind)} · ${esc(c.author)}</b><p>${esc(c.text)}</p>${interactive&&c.kind!=='CORRECTION'?`<button data-propose-comment="${c.id}">Propose lasting lesson</button>`:''}</article>`).join('');}
function findingBrief(f,interactive=true){return `<div class="callout"><span class="chip">${f.agent?'AI draft':'Editorial draft'} · v${f.version} · ${esc(reviewStatus(f.id))}</span><h2>${esc(f.headline)}</h2>${sectionHeading(f,'rationale','Recommendation',interactive)}<p><strong>${esc(actionNames[f.action])}</strong></p><p>${esc(f.rationale)}</p>${sectionComments(f,'rationale',interactive)}<p class="muted">${esc(f.confidence)} confidence · ${esc(f.author)} · ${date(f.created_at)}</p></div><div class="section">${sectionHeading(f,'observed','What we observed',interactive)}${f.agent?f.agent.citations.map((c,i)=>`<div class="note"><p>${esc(c.text)} <a href="${esc(c.url)}" target="_blank" rel="noreferrer">[${i+1}]</a></p><details><summary>Supporting passage · ${date(c.retrieved_at)}</summary><blockquote>${esc(c.quote)}</blockquote></details></div>`).join(''):`<p class="longtext">${esc(f.observed)}</p>`}<a href="${esc(f.source_url)}" target="_blank" rel="noreferrer">Inspected source ↗</a><p class="muted">Coverage: ${esc(f.coverage)}. ${f.agent?'Exact supporting passages checked against retrieved text; factual interpretation still needs admin review.':'Inspection reported by the reviewer; not independently verified.'}</p>${sectionComments(f,'observed',interactive)}${sectionHeading(f,'meaning','What it may mean for Bumpp · interpretation',interactive)}<p class="longtext">${esc(f.meaning)}</p>${sectionComments(f,'meaning',interactive)}${sectionHeading(f,'gaps','What we still need to know',interactive)}<p class="longtext">${esc(f.gaps)}</p>${sectionComments(f,'gaps',interactive)}${sectionHeading(f,'next_step','Next action · '+f.owner,interactive)}<p>${esc(f.next_step)}</p>${sectionComments(f,'next_step',interactive)}${f.test?`<h3>Proposed test · not authorized or run</h3><p>${esc(f.test)}</p><p><b>Success measure:</b> ${esc(f.success_measure)}</p><p><b>Evidence against the hypothesis:</b> ${esc(f.disconfirming_result)}</p>`:''}</div>`;}
function researchStatus(s){return s.age_status==='MATURE_LABEL_REVIEW_REQUIRED'?'Suitability review first':'Needs content inspection';}
function renderResearchDetail(item){
 const s=item.latest,f=latestFinding(item.id),history=(state.findings||[]).filter(x=>x.candidate_id===item.id).sort((a,b)=>b.version-a.version);
 $('#detail').innerHTML=`<div class="detail"><span class="chip">${f?'Research brief · editorial draft':'Unresearched lead'}</span><h2>${esc(s.title)}</h2><p class="muted">${esc(s.channel_name)} · ${esc(s.genre||s.kind)}</p>${f?`<button class="primary" id="whole-brief-feedback">Give feedback on the whole brief</button>`+findingBrief(f)+editorialPanel(f):`<div class="callout"><h3>${researchStatus(s)}</h3><p>${s.age_status==='MATURE_LABEL_REVIEW_REQUIRED'?'The listing is marked mature. Review its content suitability before using it as a reference for our young audience.':'We found this title in a catalog. Read its synopsis and inspect relevant material before deciding whether it deserves further research.'}</p><p><b>Decision supported now:</b> ${s.age_status==='MATURE_LABEL_REVIEW_REQUIRED'?'Hold for suitability review.':'Investigate or deprioritize after inspecting the title.'}</p><p><b>What this does not tell us:</b> whether our audience likes it, why its story works, or what Bumpp should produce.</p></div>`}<div class="actions"><a href="${esc(s.url)}" target="_blank" rel="noreferrer">Open title to research ↗</a><button class="primary" id="research-title">${f?'Research again':'Research this title'}</button><button id="write-finding">${f?'Revise brief':'Add manual finding'}</button>${f?'<button id="accept-finding">Accept brief</button><button id="dismiss-finding">Dismiss brief</button>':''}</div><details class="section"><summary>Discovery evidence · ${date(s.observed_at)}</summary><a href="${esc(s.discovered_on)}" target="_blank" rel="noreferrer">Discovery page ↗</a>${s.listings.map(o=>`<div class="note"><strong>${esc(o.section)}</strong><p>${esc(o.excerpt)}</p>${o.displayed_views?`<p>Displayed series views: ${esc(o.displayed_views)} · rounded source label, not unique viewers.</p>`:''}</div>`).join('')}<p class="muted">${s.age_status==='MATURE_LABEL_REVIEW_REQUIRED'?'Mature label present.':'Age suitability has not been verified.'} ${s.limitations.map(esc).join(' ')}</p></details>${history.length?`<details class="section"><summary>Brief history · ${history.length} versions</summary>${history.map(x=>`<details><summary>v${x.version} · ${esc(x.author)} · ${date(x.created_at)}</summary>${findingBrief(x,false)}</details>`).join('')}</details>`:''}<details class="section"><summary>Earlier notes and decisions</summary>${item.notes.map(n=>`<p>${esc(n.author)}: ${esc(n.text)}</p>`).join('')||'<p>No earlier evidence notes.</p>'}${item.decisions.map(d=>`<p>${esc(d.author)}: ${esc(d.rationale)}</p>`).join('')}</details></div>`;
 bindEditorial();
 $('#write-finding').onclick=()=>findingForm(item);
 $('#research-title').onclick=()=>startResearch([item.id]);
 if(f){$('#whole-brief-feedback').onclick=()=>wholeBriefFeedback(f);$('#accept-finding').onclick=()=>reviewFinding(f,'ACCEPTED');$('#dismiss-finding').onclick=()=>reviewFinding(f,'DISMISSED');}
 $('#detail').insertAdjacentHTML('afterbegin',researchProgress());
}
function findingForm(item){
 const f=latestFinding(item.id)||{};
 const field=(key,title,placeholder='',limit=3000)=>`<label>${title}<textarea name="${key}" required maxlength="${limit}" placeholder="${esc(placeholder)}">${esc(f[key]||'')}</textarea></label>`;
 openModal(`<h2>${f.version?'Revise':'Record'} findings brief</h2><p>${esc(item.latest.title)} · Write from material actually inspected. Saving creates an editorial draft, not a validated audience finding or production approval.</p><form id="finding-form" class="form"><label>Researcher<input name="author" required maxlength="100" value="${esc(f.agent?'':f.author||'')}"></label><label>Finding in one sentence<input name="headline" required maxlength="200" value="${esc(f.headline||'')}" placeholder="State the specific observation, not a generic research promise"></label><label>Inspected source link<input name="source_url" type="url" required maxlength="2000" value="${esc(f.source_url||item.latest.url)}"></label>${field('coverage','What did you inspect?','Synopsis only, or episode / scene / timestamp; name omissions',1000)}${field('observed','What did you actually observe?','Describe the evidence. Separate story features from performance claims.',6000)}${field('meaning','What might this mean for Bumpp?','Explain the connection to an audience hypothesis. This is interpretation.')}<label>Recommended action<select name="action">${Object.entries(actionNames).map(([k,v])=>`<option value="${k}" ${f.action===k?'selected':''}>${v}</option>`).join('')}</select></label>${field('rationale','Why this action?','Explain how the observation supports the recommendation.')}<label>Confidence in this recommendation<select name="confidence">${['Low','Medium','High'].map(x=>`<option ${f.confidence===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('gaps','What is missing or could contradict this?','Include audience fit, sample limitations and alternative explanations.')}${field('next_step','Concrete next step','Describe the next research action or comparison.',2000)}<label>Who owns the next step?<input name="owner" required maxlength="100" value="${esc(f.owner||'')}" placeholder="Person or team role"></label><details ${f.action==='PROPOSE_TEST'?'open':''}><summary>If proposing a test · complete all three</summary>${['test','success_measure','disconfirming_result'].map(k=>`<label>${esc({test:'Proposed test',success_measure:'Success measure and threshold',disconfirming_result:'Result that would challenge the hypothesis'}[k])}<textarea name="${k}" maxlength="${k==='test'?2000:1000}">${esc(f[k]||'')}</textarea></label>`).join('')}</details><label class="inline"><input name="inspection_confirmed" type="checkbox" required>I inspected the material described above; limitations are stated.</label><div id="finding-error" class="errors" role="alert"></div><button class="primary">Save findings draft</button></form>`);
 $('#finding-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/finding',{...Object.fromEntries(new FormData(e.target)),candidate_id:item.id,base_version:f.version||0,inspection_confirmed:e.target.inspection_confirmed.checked});$('#modal').close();await refresh();toast('Findings draft saved. No production or test has been started.');}catch(err){$('#finding-error').textContent=err.message;b.disabled=false;}};
}
function renderFindings(){
 const items=state.candidates.filter(c=>c.latest.origin==='catalog_title');
 const researched=items.filter(c=>latestFinding(c.id)),pending=items.filter(c=>!latestFinding(c.id));
 const visibleFindings=researched.filter(c=>reviewStatus(latestFinding(c.id).id)!=='DISMISSED');
 const mature=pending.filter(c=>c.latest.age_status==='MATURE_LABEL_REVIEW_REQUIRED');
 $('#overview').innerHTML=[['Findings drafts',researched.length],['Awaiting research',pending.length],['Need maturity review',mature.length],['Original page captures',state.candidates.filter(c=>c.latest.origin==='firecrawl').length]].map(([a,b])=>`<div class="stat"><span>${a}</span><b>${b}</b></div>`).join('');
 $('#workspace').innerHTML=`<div class="actions"><button class="primary" id="research-batch">Run research batch</button><button id="research-settings">Research connection</button><button id="editorial-memory">Editorial memory</button></div>${researchProgress()}<div class="callout"><h2>${visibleFindings.length?'What the research recommends':'No researched findings yet'}</h2><p>${visibleFindings.length?'Read the evidence and reasoning behind each editorial recommendation. These are drafts; no test or production starts automatically.':`We have ${items.length} title leads from captured catalogs. They tell us what exists, but not what works for Bumpp. Click Research this title or Run research batch to retrieve source-page evidence and draft a cited brief for review.`}</p></div><div class="section"><h2>Decisions supported by the evidence we have</h2><p><b>${mature.length} leads need suitability review.</b> Their source listings carry mature labels; keep that separate from creative relevance.</p><p><b>${pending.length} leads need a findings brief.</b> Their catalog records alone do not support a creative recommendation.</p><p><b>Do not change our creative frameworks from these listings alone.</b> A catalog placement is a discovery signal, not proof of audience appeal.</p></div><div class="section"><h2>Findings ready to discuss · review status shown</h2>${visibleFindings.map(c=>{const f=latestFinding(c.id);return `<article class="panel setup-card"><span class="chip">${esc(actionNames[f.action])} · ${esc(f.confidence)} confidence · ${esc(reviewStatus(f.id))}</span><h3>${esc(f.headline)}</h3><p>${esc(c.latest.title)} · ${esc(f.author)}</p><p>${esc(f.rationale)}</p><p><b>Next:</b> ${esc(f.next_step)} · ${esc(f.owner)}</p><button data-open-research="${c.id}">Read evidence &amp; brief</button></article>`;}).join('')||'<p class="muted">No active briefs yet. Run a research batch to generate cited drafts. Dismissed briefs remain in each title’s history.</p>'}</div><div class="section"><h2>Choose a lead to investigate</h2><p class="muted">Alphabetical examples, not a popularity ranking. Open the discovery inbox to search all titles.</p><button id="all-research">Browse all title leads</button><div class="setup-grid">${pending.sort((a,b)=>a.latest.title.localeCompare(b.latest.title)).slice(0,6).map(c=>`<article class="panel setup-card"><span class="chip">${esc(researchStatus(c.latest))}</span><h3>${esc(c.latest.title)}</h3><p>${esc(c.latest.channel_name)} · ${esc(c.latest.genre||c.latest.kind)}</p><button data-open-research="${c.id}">Start research</button></article>`).join('')}</div></div>`;
 document.querySelectorAll('[data-open-research]').forEach(b=>b.onclick=()=>{selected=b.dataset.openResearch;recordKind='titles';feed='';search='';view='inbox';render();});
 $('#research-batch').onclick=researchBatchForm;$('#research-settings').onclick=researchConnectionForm;$('#editorial-memory').onclick=memoryPanel;
 $('#all-research').onclick=()=>{view='inbox';recordKind='titles';search='';feed='';render();};
}

function reviewStatus(id){return state.research_agent?.reviews.find(r=>r.finding_id===id)?.status||'Awaiting review';}
function researchProgress(){
 const q=state.research_agent?.allowance;
 const allowance=q?`<p class="callout">Today: <b>${q.model_remaining} of ${q.model_limit}</b> research requests remaining · <b>${q.pages_remaining} of ${q.page_limit}</b> source-page requests remaining. Resets at 00:00 UTC. Provider billing is separate.</p>`:'';
 const runs=(state.research_agent?.runs||[]).slice(0,3);
 return allowance+(runs.length?`<div class="section"><h3>Research progress</h3>${runs.map(r=>`<details ${r.status==='RUNNING'?'open':''}><summary>${date(r.created_at)} · ${esc(r.status)}</summary>${r.jobs.map(j=>`<p><b>${esc(j.title)}</b> · ${esc(j.status)}${j.error?`<br><span class="errors">${esc(j.error)}</span>`:''}</p>`).join('')}</details>`).join('')}</div>`:'');
}
function researchConnectionForm(){
 const a=state.research_agent;
 openModal(`<h2>Research provider</h2><p>Choose who drafts and revises briefs. The selected provider receives source text, feed objectives, approved frameworks and lessons; revisions also include your prior brief and comments. Firecrawl collection and browser dictation are separate.</p><form id="research-connection" class="form"><label>Provider<select name="provider" id="research-provider"><option value="anthropic" ${a.provider==='anthropic'?'selected':''}>Claude · Anthropic</option><option value="openai" ${a.provider==='openai'?'selected':''}>OpenAI</option></select></label><p id="provider-status"></p><label>API key<input type="password" name="key" autocomplete="off" maxlength="500"></label><label>Model ID<input name="model" required maxlength="100"></label><p>Keys are saved separately and stay private. Leave the key blank to reuse this provider’s saved key. Saving switches future runs without making paid calls; queued runs keep their original provider and model. No automatic fallback between providers.</p><div id="research-error" class="errors" role="alert"></div><button class="primary">Save provider settings</button></form>`);
 const form=$('#research-connection');
 function selectedProvider(){const p=a.providers[form.elements.provider.value];form.elements.key.value='';form.elements.key.required=!p.configured;form.elements.key.placeholder=p.configured?'Leave blank to keep saved key':'Enter this provider’s API key';form.elements.model.value=p.model;$('#provider-status').textContent=p.configured?'Key configured; live access is verified when you run research.':'API key needed.';}
 $('#research-provider').onchange=selectedProvider;selectedProvider();
 form.onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/research/connect',Object.fromEntries(new FormData(e.target)));e.target.reset();$('#modal').close();await refresh();toast('Provider settings saved. Future research and revisions use this provider.');}catch(err){$('#research-error').textContent=err.message;b.disabled=false;}};
}
async function startResearch(ids,revision=false){
 if(!state.research_agent.model_configured||!state.research_agent.firecrawl_configured){researchConnectionForm();return;}
 try{await api('/api/research/start',{candidate_ids:ids,revision});$('#modal').close();await refresh();toast('Research started. Progress updates automatically; completed drafts appear in Findings.');}catch(err){toast(err.message,true);}
}
function researchBatchForm(){
 const items=state.candidates.filter(c=>c.latest.origin==='catalog_title').sort((a,b)=>a.latest.title.localeCompare(b.latest.title));
 openModal(`<h2>Research a small batch</h2><p>Select up to 3 titles. The agent retrieves each title page and drafts a cited brief using your feed objectives and approved framework. Provider credits may be used. No episodes are inspected.</p><input id="research-search" placeholder="Filter titles…" aria-label="Filter research titles"><form id="research-batch-form" class="form"><div class="research-picker">${items.map(c=>`<label class="inline" data-research-label="${esc(c.latest.title.toLowerCase())}"><input type="checkbox" name="candidate" value="${c.id}"><span>${esc(c.latest.title)} · ${esc(c.latest.channel_name)}</span></label>`).join('')}</div><div id="research-error" class="errors" role="alert"></div><button class="primary">Start research</button></form>`);
 $('#research-search').oninput=e=>document.querySelectorAll('[data-research-label]').forEach(el=>el.hidden=!el.dataset.researchLabel.includes(e.target.value.toLowerCase()));
 $('#research-batch-form').onsubmit=async e=>{e.preventDefault();const ids=new FormData(e.target).getAll('candidate');if(!ids.length||ids.length>3){$('#research-error').textContent='Choose one to three titles.';return;}await startResearch(ids);};
}
function reviewFinding(f,status){
 openModal(`<h2>${status==='ACCEPTED'?'Accept':'Dismiss'} this brief</h2><p>This records an editorial review of version ${f.version}. Accepting does not validate demographics, approve a framework change or start production.</p><form id="review-finding-form" class="form"><label>Your name<input name="author" required maxlength="100"></label><label>Review note (optional)<textarea name="note" maxlength="2000"></textarea></label><div id="research-error" class="errors" role="alert"></div><button class="primary">${status==='ACCEPTED'?'Accept brief':'Dismiss brief'}</button></form>`);
 $('#review-finding-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/finding/review',{...Object.fromEntries(new FormData(e.target)),finding_id:f.id,status});$('#modal').close();await refresh();toast('Editorial review saved for this version.');}catch(err){$('#research-error').textContent=err.message;}};
}

const feedbackSections={general:'Whole brief',observed:'What we observed',meaning:'Bumpp interpretation',rationale:'Recommendation',gaps:'Missing evidence',next_step:'Next step'};
function editorialPanel(f){
 const comments=(state.editorial?.comments||[]).filter(c=>c.finding_id===f.id);
 const notes=f.agent?.creative_notes;
 const prior=(state.findings||[]).find(x=>x.id===f.agent?.revises);
 return `<section class="section"><h3>Creative development notes</h3>${notes?Object.entries({writing:'Writer’s notes',directing:'Director’s notes',producing:'Producer’s notes',bumpp_opportunity:'Bumpp opportunity · hypothesis',smallest_test:'Smallest useful test · proposed'}).map(([k,t])=>`<h4>${t}</h4><p class="longtext">${esc(notes[k])}</p>`).join(''):'<p>Run research again to generate the new creative-development format. Scene-level conclusions require scene evidence.</p>'}<p class="muted">Editorial lessons used: ${(f.agent?.lesson_ids||[]).map(id=>{const l=state.editorial?.lessons.find(x=>x.id===id);return l?esc(l.text):'Lesson unavailable';}).join(' · ')||'None'}</p></section><section class="section"><h3>Feedback on version ${f.version}</h3>${sectionComments(f,'general',true)}<p>${comments.length} comment${comments.length===1?'':'s'} on this version. Add feedback beside the relevant section above, then revise the brief.</p><button data-revise-finding="${f.id}" ${comments.length?'':'disabled'}>Revise using feedback</button>${f.agent?.feedback_response?`<h4>Agent’s revision explanation · review required</h4><p>${esc(f.agent.feedback_response)}</p>`:''}${prior?`<details><summary>Compare with version ${prior.version}</summary>${Object.entries(feedbackSections).filter(([k])=>prior[k]!==f[k]).map(([k,t])=>`<h4>${t}</h4><p><b>Before:</b> ${esc(prior[k])}</p><p><b>After:</b> ${esc(f[k])}</p>`).join('')||'<p>No changes to the main brief sections.</p>'}</details>`:''}</section>`;
}
function bindEditorial(){
 document.querySelectorAll('[data-comment-section]').forEach(b=>b.onclick=()=>feedbackForm(b.dataset.commentFinding,b.dataset.commentSection));
 document.querySelectorAll('[data-revise-finding]').forEach(b=>b.onclick=()=>{const f=state.findings.find(x=>x.id===b.dataset.reviseFinding);startResearch([f.candidate_id],true);});
 document.querySelectorAll('[data-propose-comment]').forEach(b=>b.onclick=()=>lessonForm(state.editorial.comments.find(c=>c.id===b.dataset.proposeComment)));
}
function feedbackForm(id,section){
 openModal(`<h2>Comment on ${esc(feedbackSections[section])}</h2><form id="feedback-form" class="form"><label>Your name<input name="author" required maxlength="100"></label><label>Feedback type<select name="kind"><option value="CORRECTION">Factual correction — needs evidence</option><option value="PREFERENCE">Creative preference</option><option value="HYPOTHESIS">Hypothesis to investigate</option></select></label><label>What should change, and why?<textarea name="text" required maxlength="2000"></textarea></label><div class="voice-comment"><p>Dictate in English, then review the text. Your browser may send audio to its speech service. The Intelligence Desk saves only the comment text you submit.</p><div class="actions"><button type="button" id="dictate-comment" aria-pressed="false">Dictate comment</button><button type="button" id="insert-transcript" disabled>Add transcript to comment</button><button type="button" id="discard-transcript" disabled>Discard transcript</button></div><p id="voice-status" role="status" aria-live="polite"></p><div id="voice-preview" class="longtext" aria-label="Draft transcript"></div></div><p>Comments go to the selected research provider when you choose Revise using feedback. Do not include private personal information.</p><div class="errors" id="editorial-error"></div><button class="primary">Save comment</button></form>`);
 voiceCleanup=attachCommentVoice({Recognition:window.SpeechRecognition||window.webkitSpeechRecognition,button:$('#dictate-comment'),insert:$('#insert-transcript'),discard:$('#discard-transcript'),status:$('#voice-status'),preview:$('#voice-preview'),field:$('#feedback-form').elements.text,save:$('#feedback-form button[type=submit]')||$('#feedback-form button.primary')});
 $('#modal').addEventListener('close',()=>{if(voiceCleanup){voiceCleanup();voiceCleanup=null;}},{once:true});
 $('#feedback-form').onsubmit=async e=>{e.preventDefault();if(e.target.querySelector('button.primary').disabled)return;try{await api('/api/editorial/comment',{...Object.fromEntries(new FormData(e.target)),finding_id:id,section});$('#modal').close();await refresh();toast('Comment saved. Choose Revise using feedback when ready.');}catch(err){$('#editorial-error').textContent=err.message;}};
}
function lessonForm(comment=null){
 const finding=comment&&state.findings.find(f=>f.id===comment.finding_id),candidate=finding&&state.candidates.find(c=>c.id===finding.candidate_id);
 openModal(`<h2>Propose a lasting editorial lesson</h2><p>Write a reusable principle in your own words. Saving creates a draft; approval is separate. Lessons persist separately from expiring source evidence and do not change the creative frameworks.</p><form id="lesson-form" class="form"><label>Your name<input name="author" required maxlength="100" value="${esc(comment?.author||'')}"></label><label>Apply to feed<select name="feed_id">${state.feeds.map(f=>`<option value="${esc(f.id)}" ${candidate?.latest.feed_ids.includes(f.id)?'selected':''}>${esc(f.id+' · '+f.name)}</option>`).join('')}</select></label><label>Lesson type<select name="kind"><option value="PREFERENCE">Editorial preference</option><option value="HYPOTHESIS" ${comment?.kind==='HYPOTHESIS'?'selected':''}>Untested hypothesis</option></select></label><label>Reusable lesson<textarea name="text" required maxlength="1500">${esc(comment?.text||'')}</textarea></label><label class="inline"><input name="retention_confirmed" type="checkbox" required>This is an original editorial lesson, without copied source passages or personal data.</label><div id="editorial-error" class="errors"></div><button class="primary">Save lesson draft</button></form>`);
 $('#lesson-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/editorial/lesson',{...Object.fromEntries(new FormData(e.target)),retention_confirmed:e.target.retention_confirmed.checked});await refresh();$('#modal').close();memoryPanel();}catch(err){$('#editorial-error').textContent=err.message;}};
}
function memoryPanel(){
 openModal(`<h2>Editorial memory</h2><p>Only approved lessons for the title’s feed enter future research. At most eight matching lessons are used, newest first. These guide creative judgment; they are not audience evidence. To edit a lesson, retire it and propose a replacement.</p><button id="new-lesson">Propose lesson</button>${(state.editorial?.lessons||[]).map(l=>`<article class="note"><b>${esc(l.feed_id)} · ${esc(l.kind)} · ${esc(l.status)}</b><p>${esc(l.text)}</p><p>${esc(l.author)} · ${date(l.created_at)}</p><button data-lesson-id="${l.id}" data-lesson-status="${l.status==='APPROVED'?'RETIRED':'APPROVED'}">${l.status==='APPROVED'?'Retire':'Approve'} lesson</button><details><summary>Approval history</summary>${l.events.map(e=>`<p>${esc(e.status)} · ${esc(e.author)} · ${date(e.created_at)}</p>`).join('')||'No decisions yet.'}</details></article>`).join('')||'<p>No lessons yet. Add feedback to a brief, then propose a lasting lesson.</p>'}`);
 $('#new-lesson').onclick=()=>{$('#modal').close();lessonForm();};
 document.querySelectorAll('[data-lesson-id]').forEach(b=>b.onclick=()=>{const id=b.dataset.lessonId,status=b.dataset.lessonStatus;$('#modal').close();openModal(`<h2>${status==='APPROVED'?'Approve':'Retire'} lesson</h2><form id="lesson-decision" class="form"><label>Reviewer<input name="author" required maxlength="100"></label><div id="editorial-error" class="errors"></div><button class="primary">Save decision</button></form>`);$('#lesson-decision').onsubmit=async e=>{e.preventDefault();try{await api('/api/editorial/lesson/decide',{id,status,author:e.target.author.value});await refresh();$('#modal').close();memoryPanel();}catch(err){$('#editorial-error').textContent=err.message;}};});
}

function wholeBriefFeedback(f,previous={}){
 openModal(`<h2>Give feedback on the whole brief</h2><p>Talk through your comments in any order. You will review the proposed section assignments before saving. Audio may be processed by your browser’s speech service; this app saves only your confirmed text.</p><form id="whole-feedback" class="form"><label>Your name<input name="author" required maxlength="100" value="${esc(previous.author||'')}"></label><label>Your feedback<textarea name="text" required maxlength="12000">${esc(previous.text||'')}</textarea></label><div class="actions"><button type="button" id="whole-dictate">Dictate feedback</button><button type="button" id="whole-insert" disabled>Add transcript</button><button type="button" id="whole-discard" disabled>Discard transcript</button></div><p id="whole-status" role="status" aria-live="polite"></p><div id="whole-preview" class="longtext"></div><p>You can dictate several times. Add each transcript, then continue. Nothing is saved yet.</p><div id="whole-error" class="errors"></div><button class="primary" type="submit">Review section assignments</button></form>`);
 const form=$('#whole-feedback');
 voiceCleanup=attachCommentVoice({Recognition:window.SpeechRecognition||window.webkitSpeechRecognition,button:$('#whole-dictate'),insert:$('#whole-insert'),discard:$('#whole-discard'),status:$('#whole-status'),preview:$('#whole-preview'),field:form.elements.text,save:form.querySelector('button.primary')});
 $('#modal').addEventListener('close',()=>{if(voiceCleanup){voiceCleanup();voiceCleanup=null;}},{once:true});
 form.onsubmit=e=>{e.preventDefault();if(form.querySelector('button.primary').disabled)return;const draft=Object.fromEntries(new FormData(form));const rows=suggestFeedbackSections(draft.text);if(!rows.length||rows.length>12||rows.some(r=>r.text.length>2000)){$('#whole-error').textContent='Use up to 12 comments, each under 2,000 characters. Combine or shorten sentences before continuing.';return;}assignmentReview(f,draft,rows);};
}
function assignmentReview(f,draft,rows){
 openModal(`<h2>Review your feedback assignments</h2><p>These are local suggestions based on section words, not an AI judgment. Ambiguous comments stay under Whole brief. Change any section or feedback type, edit the wording, or uncheck a comment to omit it.</p><details><summary>Original transcript</summary><p class="longtext">${esc(draft.text)}</p></details><form id="assignment-form" class="form">${rows.map((r,i)=>`<fieldset data-assignment="${i}"><legend>Comment ${i+1}</legend><label class="inline"><input type="checkbox" name="include" checked>Include this comment</label><label>Section<select name="section">${Object.entries(feedbackSections).map(([k,t])=>`<option value="${k}" ${r.section===k?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Feedback type<select name="kind"><option value="PREFERENCE">Creative preference</option><option value="CORRECTION">Factual correction — needs evidence</option><option value="HYPOTHESIS">Hypothesis to investigate</option></select></label><label>Comment<textarea name="text" maxlength="2000">${esc(r.text)}</textarea></label></fieldset>`).join('')}<p>Saving sends the selected feedback and prior brief to the selected research provider for revision, and uses the existing research credits. It does not approve a lasting lesson.</p><div id="assignment-error" class="errors" role="alert"></div><button type="button" id="back-to-transcript">Back to original transcript</button><button class="primary" type="submit">Save all and revise</button></form>`);
 const token=crypto.randomUUID(),form=$('#assignment-form');
 $('#back-to-transcript').onclick=()=>wholeBriefFeedback(f,draft);
 form.onsubmit=async e=>{e.preventDefault();const comments=[...form.querySelectorAll('[data-assignment]')].filter(el=>el.querySelector('[name=include]').checked).map(el=>({section:el.querySelector('[name=section]').value,kind:el.querySelector('[name=kind]').value,text:el.querySelector('[name=text]').value}));const submit=form.querySelector('button.primary');submit.disabled=true;try{await api('/api/editorial/feedback-revise',{finding_id:f.id,author:draft.author,comments,request_id:token});$('#modal').close();await refresh();toast('All selected comments saved. Revision queued; progress appears with your brief.');}catch(err){$('#assignment-error').textContent=err.message;submit.disabled=false;}};
}
